import {defaults,limits,validate,calculate,costFields,validateCosts} from './calc.mjs';
import {models,checked} from './models.mjs';
import {workflows,workflowTotals,applyWorkflow} from './workflows.mjs';
import {infraScenarios,infraFields,infrastructureScenario} from './infrastructure.mjs';
let infraId='small-pilot',infraOverrides={};
let exampleId='support',loadedExample='support';
let state={...defaults}, additionalCosts={}, view='api', count=3;
const makeModel=i=>({...models[i],success:80,edited:false});
let selected=[makeModel(0),makeModel(2),makeModel(4)];
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n===null?'—':n>0&&n<.00005?'<$0.0001':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:n>0&&n<.1?4:2}).format(n);
const num=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:1}).format(n);const pct=n=>(n*100).toFixed(1)+'%';
const fields=[['input','Text sent to AI / call (tokens)','One call is one request to the AI; use the average text size'],['cached','Cached input tokens / call','Eligible reads only; 0 = uncached'],['output','AI answer size / call (tokens)','Average across calls; include billed reasoning'],['calls','AI calls to complete one task','One task may need several AI requests; a retry repeats them'],['volume','Business tasks / month','Same volume for all models']];
const flow=[['retries','Maximum retries','0 means one attempt; retry only failures'],['toolCalls','Paid lookups or actions / attempt','For example, searching a paid information service'],['toolCost','Cost / tool call (USD)','Exclude fees already in token prices'],['escalate','Unresolved tasks sent to a person (%)','After all AI attempts fail'],['humanCost','Cost each time a person helps (USD)','Charged whether the human resolves it or not'],['humanSuccess','Tasks resolved by that person (%)','Of the tasks sent to a person']];
function field([k,label,hint]){return `<label class="field" for="${k}">${label}<input id="${k}" data-key="${k}" type="number" min="${limits[k][0]}" max="${limits[k][1]}" step="${['input','cached','output','calls','volume','retries'].includes(k)?1:'any'}" value="${state[k]}"><small>${hint}</small></label>`;}

function drawExamples(){
$('#workflow-examples').innerHTML=workflows.map((p,i)=>{const t=workflowTotals(p);return `<button class="example-card" data-example="${p.id}" aria-pressed="${p.id===exampleId}" aria-controls="example-detail"><span class="model-letter">EXAMPLE 0${i+1} · ${t.calls} ${t.calls===1?'CALL':'CALLS'}</span><strong>${p.name}</strong><span>${num(t.input)} input + ${num(t.output)} output</span><small>tokens per task attempt</small></button>`;}).join('');
const p=workflows.find(p=>p.id===exampleId),t=workflowTotals(p);
$('#example-detail').innerHTML=`<div class="example-detail"><div class="example-story"><span class="tiny">${p.unit.toUpperCase()}</span><h3>${p.name}</h3><p>${p.description}</p><button class="load-example" data-load="${p.id}">Load into calculator</button><p class="example-load-note">Loads token counts, calls and the example's tool fees; clears cached reads. Your models, prices, volume, success, retries, human and additional operating-cost assumptions stay as they are. Review operating costs for the new example.</p></div><div class="example-breakdown">${p.steps.map((step,i)=>`<div class="example-step"><div class="step-title"><span>${i+1}</span><strong>${step.name}</strong><small>MODEL CALL ${i+1}</small></div><div class="step-content"><div><span class="token-direction">INPUT · WHAT IT READS</span>${step.inputParts.map(([label,n])=>`<div class="token-line"><span>${label}</span><b>${num(n)}</b></div>`).join('')}<div class="token-line token-total"><span>Total input</span><b>${num(step.inputParts.reduce((n,p)=>n+p[1],0))}</b></div></div><div class="step-output"><span class="token-direction">OUTPUT · WHAT IT WRITES</span><p>${step.outputLabel}</p><strong>${num(step.output)} <small>tokens</small></strong></div></div></div>`).join('')}<div class="example-total"><strong>One task attempt</strong><span>${t.calls} ${t.calls===1?'call':'calls'} · <b>${num(t.input)} input</b> + <b>${num(t.output)} output</b> tokens</span></div><p class="normalization">${t.calls>1?`Calculator mapping: ${num(t.input)} ÷ ${t.calls} = ${num(t.averageInput)} average input tokens per call; ${num(t.output)} ÷ ${t.calls} = ${num(t.averageOutput)} average output tokens per call. Multiplying by ${t.calls} calls recovers the task totals exactly. All calls use the same selected model and token rates. Each step must still fit that model's limits.`:'Calculator mapping: one call per task, so per-call and per-task token counts are the same.'} This is one complete attempt, before any retries.</p><p class="normalization">${p.toolCalls?`Illustrative extra fee: ${p.toolCalls} help-article lookup × $${p.toolCost} per task attempt, included only in Workflow cost. Article text is already included in input tokens.`:'No separately charged tool call is assumed. Supplied text is already available.'} ${p.id==='extraction'?'Scans, images and OCR costs are not included.':''}</p></div></div>`;
}
function loadExample(id){const p=workflows.find(p=>p.id===id);state=applyWorkflow(state,p);loadedExample=id;exampleId=id;drawFields();drawModels();drawExamples();drawInfra();render();$('#example-detail [data-load]').focus();$('#workload-context').textContent=p.name+' example loaded. Identical token counts and calls for every model.';$('#preset-status').textContent='Loaded: '+p.name+'. Review the calculator below. Success and retry assumptions were not changed.';}
document.addEventListener('click',e=>{if(e.target.closest('[data-infra-update]'))drawInfraSummary();const infra=e.target.closest('[data-infra-preset]');if(infra){infraId=infra.dataset.infraPreset;infraOverrides={};drawInfra();}const example=e.target.closest('[data-example]');const load=e.target.closest('[data-load]');if(example){exampleId=example.dataset.example;drawExamples();$('#workflow-examples [data-example="'+exampleId+'"]').focus();}if(load)loadExample(load.dataset.load);});

function drawInfraSummary(){try{const p=infrastructureScenario(infraId,infraOverrides),a=p.assumptions,c=p.additional_costs;$('#infra-summary').innerHTML=`<p class="hint"><b>Example document library:</b> about ${num(p.document_equivalents.approx_pdfs)} ten-page PDFs <b>or</b> ${num(p.document_equivalents.approx_articles)} short articles. These are alternative ways to picture the same amount of text, not files we measured.</p><details><summary>How we translate PDFs and articles into a budget</summary><p class="hint">Assume an English PDF has 10 pages with 500 words per page, or an article has 1,000 words. For this illustration only, allow about 4 tokens for every 3 words, plus 25% extra for text repeated between searchable passages. That gives about 8,333 embedded tokens per PDF or 1,667 per article. Actual files, languages and AI tokenizers vary.</p><p class="hint">This example budgets ${num(a.chunks)} searchable passages × ${num(a.tokensPerChunk)} tokens = ${num(a.chunks*a.tokensPerChunk)} tokens to prepare the library. The document equivalents help explain that existing budget; they do not change the calculation.</p><p class="hint">Prepare the whole library for search once. For each question, find a few relevant passages and send those to the answering AI. You do not send the whole library with every question. The calculator’s input-token field covers the instructions, question and retrieved text actually sent to the AI.</p><p class="hint">Text must already be readable. Scanned PDFs need text extraction (OCR); images, complex tables, cleanup and connecting the search system can add costs. Those amounts are still unknown here.</p></details><div class="infra-totals"><span>Make documents searchable · one-time <b>${money(c.setupEmbeddings)}</b></span><span>Run the service + store information · monthly <b>${money(c.compute+c.vectorStorage)}</b></span><span>Support and upkeep · monthly <b>${money(c.maintenance)}</b></span></div><p class="hint"><b>Example operating budget: ${money(p.reference.known_monthly_including_amortized_embeddings_and_labour_usd)} / month, with costs still missing.</b> Based on ${num(a.attempts)} search attempts a month, including repeats. This spreads the one-time search preparation over 12 months and includes search fees, hosting and ${num(a.labourHours)} hours of upkeep at ${money(a.labourRate)}/hour. The hours and hourly rate are invented planning assumptions.</p><p class="notice">Not a total project quote. AI answers, document cleanup and connecting the search system still need a budget. These example resources have not been tested to handle the illustrated volume.</p><p class="hint"><b>Preview only.</b> The button below replaces your additional operating costs and opens Workflow cost. Your task volume, retries and model choices stay unchanged, so your calculated monthly cost may differ from this example.</p><p id="infra-edit-status" role="alert"></p><button id="infra-load" class="load-example" ${p.can_load?'':'disabled'}>Use this example in Workflow cost</button><details><summary>What is included, and what still needs a budget?</summary><p class="hint">“Make documents searchable” pays for converting existing text into a form the search system can match to questions (embeddings). It does not pay for cleaning files, reading scanned pages or connecting and organizing the search system. Those costs remain unknown.</p><p class="hint">“Run the service + store information” covers the assumed hosting and database bill. Searching existing information is included in this hosting budget. Support and upkeep is a separate human-work allowance, not a provider fee.</p><p class="hint">Loading uses a 12-month spread for setup and assigns 100% of these shared costs to this workload. Usage fees apply again when a task is retried. The monthly hosting budget does not automatically increase with your task volume.</p><p class="hint">This example assumes the documents do not change during the month. Updating them, backups, standby systems for outages and separate file storage are not budgeted. No extra service for reordering search results is assumed. Monitoring uses the hosting provider’s basic usage charts. AI answers and any human help resolving customer tasks are calculated separately below.</p></details><details><summary>Edit business assumptions</summary><div class="infra-inputs">${infraFields.filter(([k])=>['attempts','chunks','labourHours','labourRate'].includes(k)).map(([k,label,max])=>`<label class="field">${label}<input type="number" min="0" max="${max}" step="any" data-infra="${k}" value="${a[k]}"></label>`).join('')}</div><button type="button" class="text-button" data-infra-update>Apply edits to preview</button><p class="hint">One document can contain many searchable passages. Search attempts include repeat attempts after a failure; they are not necessarily distinct customer requests. Editing the reference volume here does not change your calculator task volume.</p></details><details><summary>Technical details and supplier prices</summary><p class="hint">Prices checked 2026-10-01. Example stack: OpenAI text-embedding-3-small and self-managed PostgreSQL/pgvector on Railway Pro. Supplier rates are sourced; sizes and labour budgets are assumptions.</p><div class="infra-inputs">${infraFields.filter(([k])=>!['attempts','chunks','labourHours','labourRate'].includes(k)).map(([k,label,max])=>`<label class="field">${label}<input type="number" min="0" max="${max}" step="any" data-infra="${k}" value="${a[k]}"></label>`).join('')}</div><button type="button" class="text-button" data-infra-update>Apply edits to preview</button><p class="hint">RAM and CPU are average usage over the month, not a machine size or a capacity recommendation. Storage means average billable disk usage. Transfer uses decimal KB/GB. Railway bills the larger of $${a.minimum} or resource usage; the minimum is not added twice.</p><p class="hint">Document passages: ${num(a.chunks)} × ${num(a.tokensPerChunk)} tokens = ${num(a.chunks*a.tokensPerChunk)} embedded tokens. Question preparation: ${num(a.queryTokens)} tokens × $${a.embeddingRate}/1M = $${c.queryEmbeddings.toFixed(8)} per complete attempt. Hosting = (${a.dbRam}+${a.appRam}) GB × $${a.ramRate} + (${a.dbCpu}+${a.appCpu}) vCPU × $${a.cpuRate} = ${money(c.compute)}/month. Database storage = ${a.storageGb} GB × $${a.diskRate} = ${money(c.vectorStorage)}/month.</p><p class="hint">If documents change, budget new/changed passages × tokens per passage × embedding rate /1M, plus import and indexing work. Initial setup remains unknown. ${p.load_note}</p>${p.sources.map(s=>`<a class="source-link" href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title} ↗</a>`).join('')}</details>${!p.can_load?`<p class="notice">${p.load_note}</p>`:''}`;$('#infra-load').onclick=()=>{additionalCosts={...p.additional_costs};drawCosts();setView('workflow');render();$('#preset-status').textContent='Loaded '+p.name+' operating-cost example. Task volume and retries are unchanged; document cleanup and search-system setup still need a budget.';};}catch(e){$('#infra-edit-status').textContent='Check the example inputs: enter numbers between zero and the displayed limits, then apply your edits again.';$('#infra-load').disabled=true;}}
function drawInfra(){$('#infra-panel').innerHTML=`<section class="infra-examples" aria-labelledby="infra-title"><p class="eyebrow">BEYOND THE AI BILL</p><h2 id="infra-title">What does it cost to keep the service running?</h2><p class="hint">Imagine a service that searches your business documents to help answer questions. You pay to make the documents searchable, keep the service available, and maintain it. Explore three illustrative budgets below.</p><div class="infra-choice-grid">${infraScenarios.map(example=>{const r=infrastructureScenario(example.id);return `<button class="infra-choice" data-infra-preset="${example.id}" aria-pressed="${example.id===infraId}"><strong>${example.name}</strong><span>About ${num(r.document_equivalents.approx_pdfs)} ten-page PDFs</span><span>or ${num(r.document_equivalents.approx_articles)} short articles</span><span>${money(r.additional_costs.compute+r.additional_costs.vectorStorage)} hosting + storage / month</span><small>${num(r.assumptions.attempts)} search attempts / month · assumed, not tested capacity</small></button>`;}).join('')}</div><p class="hint">Choose a card to preview it. These are examples using one provider setup, not standard prices or recommended plans for your business.</p><label class="field">Example to explore<select id="infra-scenario">${infraScenarios.map(p=>`<option value="${p.id}" ${p.id===infraId?'selected':''}>${p.name}</option>`).join('')}</select></label><div id="infra-summary"></div></section>`;$('#infra-scenario').onchange=e=>{infraId=e.target.value;infraOverrides={};drawInfra();};drawInfraSummary();}
function drawCosts(){const groups=[['setup','One-time setup budget','Spread the initial work across the months you expect to use it'],['variable','Costs each time the task is attempted','Repeats on every retry, not every model call. Sum measured units × unit rates before entering. If incurred only once per task, use a monthly budget based on expected task volume instead.'],['fixed','Monthly running costs','Enter the whole shared budget; the allocation below selects this workload’s share']];$('#cost-fields').innerHTML=groups.map(([group,title,hint])=>`<h3>${title}</h3><p class="hint">${hint}</p>${costFields.filter(f=>f[2]===group).map(([k,label])=>`<label class="field">${label}<input type="number" min="0" max="1000000000" step="any" placeholder="Not provided" data-cost="${k}" value="${additionalCosts[k]??''}"></label>`).join('')}`).join('')+`<label class="field">Spread setup over (months)<input type="number" min="1" max="1200" step="1" data-cost="amortizationMonths" value="${additionalCosts.amortizationMonths??12}"><small>Default: 12 months. This spreads the estimate; it does not change when you pay</small></label><label class="field">Share of setup and monthly costs used by this project (%)<input type="number" min="0" max="100" step="any" data-cost="allocatedSharePercent" value="${additionalCosts.allocatedSharePercent??100}"><small>Applies to setup and monthly costs only. Use 100% if this project uses the whole budget</small></label>`;}
function drawFields(){$('#base-inputs').innerHTML=fields.map(field).join('');$('#flow-fields').innerHTML=flow.map(field).join('');drawCosts();}
function drawModels(){$('#model-controls').innerHTML=`<div class="model-grid" style="--columns:${count}">${selected.slice(0,count).map((m,i)=>`<article class="model-card" style="--accent:var(--${'abc'[i]})"><div class="model-letter">MODEL ${'ABC'[i]} · ${esc(m.provider)}</div><label for="model-${i}" class="sr-only">Model ${'ABC'[i]}</label><select id="model-${i}" class="model-select" data-model="${i}">${models.map(t=>`<option value="${t.id}" ${t.id===m.id?'selected':''}>${t.name}</option>`).join('')}<option value="custom" ${m.id==='custom'?'selected':''}>Custom model</option></select>${m.id==='custom'?`<label class="field custom-name">Model name<input maxlength="60" data-name="${i}" value="${esc(m.name)}"></label>`:''}<p class="rate-note">USD / 1M tokens · ${m.edited?'edited rates':'source snapshot'}</p><div class="rate-grid">${[['input','Input'],['output','Output'],['cached','Cache read']].map(([k,l])=>`<label class="field" for="rate-${i}-${k}">${l}<input id="rate-${i}-${k}" type="number" min="0" max="1000000" step="any" value="${m[k]}" data-rate="${i}" data-prop="${k}"></label>`).join('')}</div>${m.url?`<a class="source-link" href="${m.url}" target="_blank" rel="noopener noreferrer">Official source ↗</a>`:''}<label class="field success-field" ${view==='api'?'hidden':''} for="success-${i}">Attempt success (%)<input id="success-${i}" type="number" min="0" max="100" step="any" value="${m.success}" data-rate="${i}" data-prop="success"><small>Your assumption; example 80% for every model</small></label></article>`).join('')}</div>`;}
function costGroupLabel(r,group,amount){const keys=costFields.filter(f=>f[2]===group).map(f=>f[0]);const missing=keys.filter(k=>r.costs.missing_cost_fields.includes(k)).length;return missing===keys.length?'Not provided':money(amount)+(missing?' known':'');}
function render(){const active=selected.slice(0,count),errors=validate(view==='api'?{...defaults,input:state.input,cached:state.cached,output:state.output,calls:state.calls,volume:state.volume}:state,view==='api'?active.map(m=>({...m,success:80})):active).concat(view==='workflow'?validateCosts(additionalCosts):[]);$('#errors').hidden=!errors.length;$('#errors').textContent=errors.length?'Check your inputs: '+errors.join('; '):'';if(errors.length){$('#results').innerHTML='<p class="notice">Results paused until the inputs are valid.</p>';return;}const results=active.map(m=>calculate(state,m,view==='workflow'?additionalCosts:undefined));const workflow=view==='workflow';const values=results.map(r=>workflow?r.costs.known_monthly_usd:r.apiMonthly);const max=Math.max(...values,1e-20);let warnings=[];
if(workflow&&!results[0].costs.complete)warnings.push('Partial cost estimate: '+results[0].costs.missing_cost_fields.length+' operating-cost categories are not provided. Known costs below exclude them; blank is not zero. Open Additional operating costs to add them, or enter 0 only after checking they do not apply.');
if(workflow)warnings.push('Illustrative scenario: every model starts at the same 80% attempt success. These are not benchmarks. Replace them with results from your own evaluation.');
if(state.cached>0)warnings.push('Warm-cache subtotal: cache-write and explicit-cache storage charges are excluded. A cache hit assumption does not guarantee eligibility or savings.');
if(active.some(m=>m.id.startsWith('gpt-'))&&state.input>272000)warnings.push('OpenAI base rates do not apply above 272,000 input tokens. Edit input/cache rates ×2 and output ×1.5 for this tier.');
if(active.some(m=>m.id==='claude-haiku-4-5-20251001')&&state.input+state.output>200000)warnings.push('This workload exceeds the Claude Haiku 4.5 context window. Reduce token counts or choose a different model.');
if(state.input>1048576||state.output>65536)warnings.push('Large token assumptions may exceed model limits. Check official context and output limits before using this estimate.');
if(active.some(m=>m.id==='gemini-3.8-flash'))warnings.push(new Date()>=new Date('2027-01-01T00:00:00Z')?'Gemini 3.8 Flash promotional preset has expired. Update to current official rates before using the estimate.':'Gemini 3.8 Flash uses promotional standard pricing through Dec 31, 2026. See sources for the next price tier.');
$('#results').innerHTML=`${warnings.map(w=>`<p class="notice">${w}</p>`).join('')}<div class="result-grid" style="--columns:${count}">${results.map((r,i)=>`<div class="result-card"><div class="result-label">${workflow?(r.costs.complete?'Per resolved task · entered scope':'Partial cost / resolved task'):'Monthly API subtotal'}</div><div class="big-number">${money(workflow?r.costs.known_cost_per_resolved_task_usd:r.apiMonthly)}</div><div class="unit">${workflow?(r.costs.complete?'Includes all entered cost categories':'Known costs only; missing costs excluded'):'USD · '+num(state.volume)+' tasks'}</div><div class="mini-stat"><span>${workflow?(r.costs.complete?'Monthly entered total':'Monthly known subtotal'):'Per task'}</span><strong>${money(workflow?r.costs.known_monthly_usd:r.perAttempt)}</strong></div></div>`).join('')}</div><div class="chart-panel"><div class="chart-header"><h3>${workflow?'Where the monthly cost goes':'Monthly token-cost comparison'}</h3><span>Same scale · USD</span></div>${results.map((r,i)=>{const parts=workflow?[[r.api*state.volume,'#2046d8'],[r.tools*state.volume,'#43a99d'],[r.human*state.volume,'#e6ac47'],[r.costs.variable_monthly,'#9359bc'],[r.costs.fixed_monthly_allocated+r.costs.setup_monthly_allocated,'#607391']]:[[r.apiMonthly,['#214be5','#149082','#8b55cc'][i]]];return `<div class="bar-row"><div class="bar-meta"><span>${esc(active[i].name)}</span><strong>${money(values[i])}</strong></div><div class="bar-track" role="img" aria-label="${esc(active[i].name)} monthly cost ${money(values[i])}">${parts.map(([v,c])=>`<div class="bar-segment" style="width:${v/max*100}%;background:${c}"></div>`).join('')}</div></div>`;}).join('')}${workflow?'<div class="legend"><span style="--key:#2046d8">Model API</span><span style="--key:#43a99d">Tools</span><span style="--key:#e6ac47">Help from people</span><span style="--key:#9359bc">Additional usage</span><span style="--key:#607391">Setup + monthly running costs</span></div>':''}<div class="table-wrap"><table><thead><tr><th scope="col">${workflow?'Expected outcomes':'Cost breakdown'}</th>${active.map(m=>`<th scope="col">${esc(m.name)}</th>`).join('')}</tr></thead><tbody>${(workflow?[['Attempts / task',r=>num(r.attempts)],['AI resolution rate',r=>pct(r.aiSuccess)],['Escalated tasks / month',r=>num(r.escalation*state.volume)],['Final resolution rate',r=>pct(r.finalSuccess)],['Resolved tasks / month',r=>num(r.successes)],['Model API / month',r=>money(r.api*state.volume)],['Tools / month',r=>money(r.tools*state.volume)],['Human / month',r=>money(r.human*state.volume)],['Additional usage / month',r=>costGroupLabel(r,'variable',r.costs.variable_monthly)],['Setup spread across months · your share',r=>costGroupLabel(r,'setup',r.costs.setup_monthly_allocated)],['Your share of monthly running costs',r=>costGroupLabel(r,'fixed',r.costs.fixed_monthly_allocated)],['Known cost / submitted task',r=>money(r.costs.known_cost_per_task_usd)],['Missing operating-cost categories',r=>String(r.costs.missing_cost_fields.length)]]:[['API / call',r=>money(r.perCall)],['API / task',r=>money(r.perAttempt)],['Calls / month',r=>num(state.calls*state.volume)]]).map(([label,fn])=>`<tr><th scope="row">${label}</th>${results.map(r=>`<td>${fn(r)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="hint" style="margin-bottom:0">${workflow?'Expected values, not a forecast. Tasks completed with human help count as successful outcomes. Known costs include only entered amounts; complete means reviewed categories, not a guarantee of every business expense. Setup and fixed budgets are allocated to each alternative model scenario, not added across models.':'Token subtotal only. Cache creation/storage and provider tool fees are not included.'}</p></div>`;}
function setView(v){view=v;$('#infra-panel').hidden=false;$('#api-tab').setAttribute('aria-selected',v==='api');$('#workflow-tab').setAttribute('aria-selected',v==='workflow');$('#results').setAttribute('aria-labelledby',v+'-tab');$('#workflow-inputs').hidden=v==='api';$('#result-title').textContent=v==='api'?'Compare the AI usage bill':'What does a successfully completed task cost?';$('#result-subtitle').textContent=v==='api'?'AI text charges only. Use Workflow cost to include running costs.':'Includes entered operating costs, repeat attempts and help from people.';drawModels();render();}
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.infra){infraOverrides[t.dataset.infra]=t.value===''?NaN:Number(t.value);$('#infra-load').disabled=true;$('#infra-load').textContent='Apply edits to preview before using this example';}if(t.dataset.cost){additionalCosts[t.dataset.cost]=t.value===''?null:Number(t.value);render();}if(t.dataset.key){state[t.dataset.key]=t.value===''?NaN:Number(t.value);if(['input','cached','output','calls','toolCalls','toolCost'].includes(t.dataset.key)){$('#workload-context').textContent='Custom workload. Identical token counts and calls for every model.';$('#preset-status').textContent='Calculator inputs edited. Example token budgets above remain illustrative references.';loadedExample=null;}render();}if(t.dataset.rate!==undefined){selected[+t.dataset.rate][t.dataset.prop]=t.value===''?NaN:Number(t.value);if(t.dataset.prop!=='success'){selected[+t.dataset.rate].edited=true;t.closest('.model-card').querySelector('.rate-note').textContent='USD / 1M tokens · edited rates';}render();}if(t.dataset.name!==undefined){selected[+t.dataset.name].name=t.value;render();}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.model!==undefined){const i=+t.dataset.model;selected[i]=t.value==='custom'?{id:'custom',provider:'Your model',name:'Custom model',input:1,output:5,cached:1,success:80,edited:true}:{...models.find(m=>m.id===t.value),success:selected[i].success,edited:false};drawModels();render();}});
$('#api-tab').onclick=()=>setView('api');$('#workflow-tab').onclick=()=>setView('workflow');$('.tabs').addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const v=e.key==='Home'?'api':e.key==='End'?'workflow':view==='api'?'workflow':'api';setView(v);$('#'+v+'-tab').focus();}});$('#count').onchange=e=>{count=+e.target.value;drawModels();render();};$('#cost-zero').onclick=()=>{for(const [k] of costFields)if(additionalCosts[k]===undefined||additionalCosts[k]===null)additionalCosts[k]=0;drawCosts();render();};$('#reset').onclick=()=>{state={...defaults};additionalCosts={};infraId='small-pilot';infraOverrides={};drawInfra();selected=[makeModel(0),makeModel(2),makeModel(4)];count=3;$('#count').value='3';exampleId='support';loadedExample='support';drawExamples();$('#workload-context').textContent='Support example loaded. Identical token counts and calls for every model.';$('#preset-status').textContent='Reset to the support example and default assumptions.';drawFields();setView(view);};
$('#source-date').textContent=`Official pricing checked ${checked} (UTC). All rates are editable.`;$('#sources').innerHTML=models.map(m=>`<div class="source-item"><a href="${m.url}" target="_blank" rel="noopener noreferrer">${m.name} · ${m.provider} ↗</a><small>Input $${m.input} / output $${m.output} / cache read $${m.cached} per 1M tokens. ${m.note}</small></div>`).join('');drawFields();drawModels();drawExamples();drawInfra();render();
